const SHELF_WALL_X = 11.5;            // A, B, C: left-wall shelves, distance from room centre
const BAY_CENTERS_Z = [-10, 0, 10];   // 3 bays along the left wall
const BAY_LENGTH = 9.2;
const SHELF_COPY_SLOTS = 40;
const SLOT_STEP = BAY_LENGTH / SHELF_COPY_SLOTS;
const BACK_WALL_Z = -15.6;            // D, E, F: 3 bays along the back wall, right of the door
const BACK_BAY_CENTERS_X = [-5.4, 1.2, 7.8];
const BACK_BAY_LENGTH = 6.6;
const BACK_SLOT_STEP = BACK_BAY_LENGTH / SHELF_COPY_SLOTS;
const DOOR_X = -9.0;                  // door on the back wall, nudged towards the shelves
const DESK_X = 8.5;                   // librarian desk on the front wall (left side as seen facing that wall)
const DESK_Z = 13.2;
const BACK_DESK_X = -5.4;             // second librarian desk on the back wall, where shelf D used to be
const BACK_DESK_Z = -14.2;
const REMOVED_ROW = 3;                // shelf D is gone; its books are re-homed on the remaining shelves
// Rows 0-2 = left wall, rows 3-5 = back wall. (fx, fz) is the direction the books face.
const bayOf = (row: number) => row < 3
  ? { x: -SHELF_WALL_X, z: BAY_CENTERS_Z[row], onBack: false, fx: 1, fz: 0, length: BAY_LENGTH, step: SLOT_STEP }
  : { x: BACK_BAY_CENTERS_X[row - 3], z: BACK_WALL_Z, onBack: true, fx: 0, fz: 1, length: BACK_BAY_LENGTH, step: BACK_SLOT_STEP };
// World position of a shelf slot (0-15) along its bay.
const slotPos = (row: number, slot: number) => {
  const b = bayOf(row);
  const safeSlot = Math.max(0, Math.min(SHELF_COPY_SLOTS - 1, slot));
  const offset = -b.length / 2 + (safeSlot + 0.5) * b.step;
  // Viewed from the room, the left-wall bays read right-to-left along +Z;
  // the back-wall bays read left-to-right along +X.
  return b.onBack ? { x: b.x + offset, z: b.z } : { x: b.x, z: b.z - offset };
};
