function makeTextTexture(title: string, accent: string) {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 256;
  const ctx = canvas.getContext("2d");
  if (!ctx) return null;
  ctx.fillStyle = "#e9dfc6";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = accent;
  ctx.fillRect(16, 0, 17, canvas.height);
  ctx.fillStyle = "#283b3d";
  ctx.font = "bold 30px Georgia";
  const words = title.split(" ");
  const lines: string[] = [];
  let line = "";
  for (const word of words) {
    const candidate = line ? `${line} ${word}` : word;
    if (ctx.measureText(candidate).width > 420 && line) { lines.push(line); line = word; }
    else line = candidate;
  }
  if (line) lines.push(line);
  const trimmed = lines.slice(0, 4);
  const total = trimmed.length * 38;
  trimmed.forEach((part, i) => ctx.fillText(part, 58, (canvas.height - total) / 2 + i * 38 + 27, 410));
  ctx.fillStyle = "#876f48";
  ctx.fillRect(58, 210, 110, 3);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

function makeSpineTexture(title: string, accent: string) {
  const canvas = document.createElement("canvas");
  canvas.width = 256; canvas.height = 512;
  const ctx = canvas.getContext("2d");
  if (!ctx) return null;
  ctx.fillStyle = "#eee4cf"; ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = accent; ctx.fillRect(0, 0, 18, canvas.height);
  ctx.fillStyle = "#263b3d"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
  let fontSize = 31; let lines: string[] = [];
  while (fontSize >= 19) {
    ctx.font = `bold ${fontSize}px Georgia`;
    lines = []; let line = "";
    for (const word of title.split(/\s+/)) {
      const candidate = line ? `${line} ${word}` : word;
      if (ctx.measureText(candidate).width > 220 && line) { lines.push(line); line = word; }
      else line = candidate;
    }
    if (line) lines.push(line);
    if (lines.length <= 8) break;
    fontSize -= 2;
  }
  const lineHeight = Math.min(52, Math.floor(420 / Math.max(1, lines.length)));
  ctx.font = `bold ${fontSize}px Georgia`;
  lines.slice(0, 8).forEach((line, i) => ctx.fillText(line, 137, (canvas.height - lines.length * lineHeight) / 2 + i * lineHeight + lineHeight / 2, 220));
  const texture = new THREE.CanvasTexture(canvas); texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

function addBox(scene: THREE.Object3D, geometry: THREE.BoxGeometry, material: THREE.Material, x: number, y: number, z: number, castShadow = false, receiveShadow = false) {
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(x, y, z);
  mesh.castShadow = castShadow;
  mesh.receiveShadow = receiveShadow;
  scene.add(mesh);
  return mesh;
}

function buildStudyTable(scene: THREE.Scene, x: number, z: number, tone: string, chairTone: string) {
  const top = new THREE.Mesh(new THREE.BoxGeometry(2.25, 0.12, 1.3), new THREE.MeshStandardMaterial({ color: tone, roughness: 0.64 }));
  top.position.set(x, 0.76, z);
  top.castShadow = true; top.receiveShadow = true; scene.add(top);
  const legMat = new THREE.MeshStandardMaterial({ color: "#4b5050", metalness: 0.25, roughness: 0.55 });
  for (const dx of [-0.83, 0.83]) for (const dz of [-0.44, 0.44]) addBox(scene, new THREE.BoxGeometry(0.08, 0.72, 0.08), legMat, x + dx, 0.36, z + dz, true);
  for (const [dx, dz] of [[-1.7,0],[1.7,0],[0,-1.18],[0,1.18]] as const) {
    const chair = new THREE.Mesh(new THREE.BoxGeometry(0.58, 0.11, 0.55), new THREE.MeshStandardMaterial({ color: chairTone, roughness: 0.78 }));
    chair.position.set(x + dx, 0.47, z + dz); chair.castShadow = true; scene.add(chair);
    const back = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.58, 0.08), new THREE.MeshStandardMaterial({ color: chairTone, roughness: 0.78 }));
    back.position.set(x + dx, 0.76, z + dz + (dz < 0 ? -0.23 : 0.23)); scene.add(back);
    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.05, 0.43, 8), legMat);
    post.position.set(x + dx, 0.23, z + dz); scene.add(post);
  }
  const laptop = new THREE.Mesh(new THREE.BoxGeometry(0.54, 0.035, 0.38), new THREE.MeshStandardMaterial({ color: "#3d4c51", metalness: 0.35, roughness: 0.4 }));
  laptop.position.set(x - 0.2, 0.84, z - 0.12); scene.add(laptop);
  const screen = new THREE.Mesh(new THREE.BoxGeometry(0.52, 0.31, 0.025), new THREE.MeshStandardMaterial({ color: "#566d73", emissive: "#263b40", emissiveIntensity: 0.4, metalness: 0.25 }));
  screen.position.set(x - 0.2, 1.0, z - 0.27); screen.rotation.x = -0.16; scene.add(screen);
}

function buildDoubleDoor(scene: THREE.Scene, x: number, z: number) {
  const frameMat = new THREE.MeshStandardMaterial({ color: "#5b4632", roughness: 0.7 });
  const doorMat = new THREE.MeshStandardMaterial({ color: "#8a6a47", roughness: 0.6 });
  const handleMat = new THREE.MeshStandardMaterial({ color: "#c9b27c", metalness: 0.7, roughness: 0.3 });
  const H = 2.5, W = 1.15;
  addBox(scene, new THREE.BoxGeometry(2 * W + 0.36, 0.14, 0.12), frameMat, x, H + 0.07, z);
  for (const s of [-1, 1]) {
    addBox(scene, new THREE.BoxGeometry(0.14, H + 0.14, 0.12), frameMat, x + s * (W + 0.1), (H + 0.14) / 2, z);
    addBox(scene, new THREE.BoxGeometry(W - 0.02, H, 0.08), doorMat, x + s * (W / 2), H / 2, z + 0.03, true);
    addBox(scene, new THREE.BoxGeometry(0.05, 0.3, 0.06), handleMat, x + s * 0.12, 1.1, z + 0.1);
  }
}

function addChair(scene: THREE.Object3D, x: number, z: number, rotY: number, mat: THREE.Material, legMat: THREE.Material) {
  const g = new THREE.Group();
  const seat = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.1, 0.55), mat); seat.position.y = 0.47;
  const back = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.55, 0.08), mat); back.position.set(0, 0.78, 0.24);
  const post = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.05, 0.43, 8), legMat); post.position.y = 0.23;
  [seat, back, post].forEach((m) => { m.castShadow = true; g.add(m); });
  g.position.set(x, 0, z); g.rotation.y = rotY; scene.add(g);
}

function buildLibrarianDesk(scene: THREE.Scene, x: number, z: number, rotY = 0) {
  // Built around the origin facing -z (counter towards the room), then moved and turned into place.
  const g = new THREE.Group();
  g.position.set(x, 0, z); g.rotation.y = rotY; scene.add(g);
  const bodyMat = new THREE.MeshStandardMaterial({ color: "#8a6a47", roughness: 0.7 });
  const topMat = new THREE.MeshStandardMaterial({ color: "#b99468", roughness: 0.6 });
  const legMat = new THREE.MeshStandardMaterial({ color: "#4b5050", metalness: 0.25, roughness: 0.55 });
  const chairMat = new THREE.MeshStandardMaterial({ color: "#57686a", roughness: 0.78 });
  addBox(g, new THREE.BoxGeometry(3.0, 1.05, 0.45), bodyMat, 0, 0.525, 0, true, true);        // front counter
  addBox(g, new THREE.BoxGeometry(3.2, 0.06, 0.65), topMat, 0, 1.08, 0, true, true);          // counter top
  addBox(g, new THREE.BoxGeometry(3.0, 0.06, 0.8), topMat, 0, 0.76, 0.62, true, true);        // working surface
  for (const dx of [-1.4, 1.4]) addBox(g, new THREE.BoxGeometry(0.06, 0.73, 0.06), legMat, dx, 0.37, 0.98, true);
  addBox(g, new THREE.BoxGeometry(0.08, 0.3, 0.08), legMat, -0.6, 0.94, 0.55);                // monitor stand
  const screen = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.38, 0.04), new THREE.MeshStandardMaterial({ color: "#566d73", emissive: "#263b40", emissiveIntensity: 0.4, metalness: 0.25 }));
  screen.position.set(-0.6, 1.27, 0.55); screen.castShadow = true; g.add(screen);
  addChair(g, 0.2, 1.2, 0, chairMat, legMat);                                                 // librarian's chair
  const canvas = document.createElement("canvas"); canvas.width = 512; canvas.height = 144;
  const ctx = canvas.getContext("2d");
  if (ctx) {
    ctx.fillStyle = "#edf0e8"; ctx.fillRect(0, 0, 512, 144);
    ctx.fillStyle = "#324f63"; ctx.font = "bold 62px Georgia"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
    ctx.fillText("Librarian", 256, 74);
    const texture = new THREE.CanvasTexture(canvas); texture.colorSpace = THREE.SRGBColorSpace;
    const sign = new THREE.Mesh(new THREE.PlaneGeometry(1.1, 0.31), new THREE.MeshBasicMaterial({ map: texture }));
    sign.position.set(0, 0.72, -0.228); sign.rotation.y = Math.PI; g.add(sign);                 // faces the room
  }
}

function buildRoundTable(scene: THREE.Scene, x: number, z: number, tone: string, chairTone: string) {
  const legMat = new THREE.MeshStandardMaterial({ color: "#4b5050", metalness: 0.25, roughness: 0.55 });
  const chairMat = new THREE.MeshStandardMaterial({ color: chairTone, roughness: 0.78 });
  const top = new THREE.Mesh(new THREE.CylinderGeometry(1.2, 1.2, 0.1, 48), new THREE.MeshStandardMaterial({ color: tone, roughness: 0.64 }));
  top.position.set(x, 0.76, z); top.castShadow = true; top.receiveShadow = true; scene.add(top);
  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 0.72, 16), legMat); stem.position.set(x, 0.36, z); scene.add(stem);
  const foot = new THREE.Mesh(new THREE.CylinderGeometry(0.6, 0.6, 0.06, 32), legMat); foot.position.set(x, 0.03, z); scene.add(foot);
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2;
    addChair(scene, x + Math.cos(a) * 1.75, z + Math.sin(a) * 1.75, Math.PI / 2 - a, chairMat, legMat);
  }
}

function buildQuietScreen(scene: THREE.Scene, x: number, y: number, z: number) {
  const frameMat = new THREE.MeshStandardMaterial({ color: "#2c3a3d", roughness: 0.5, metalness: 0.3 });
  addBox(scene, new THREE.BoxGeometry(4.8, 1.6, 0.12), frameMat, x, y, z, true);
  const canvas = document.createElement("canvas"); canvas.width = 1024; canvas.height = 320;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.fillStyle = "#16292e"; ctx.fillRect(0, 0, 1024, 320);
  ctx.textAlign = "center"; ctx.textBaseline = "middle";
  ctx.fillStyle = "#f0e8d2"; ctx.font = "bold 150px Georgia"; ctx.fillText("Keep quiet", 512, 140);
  ctx.fillStyle = "#9fb7ba"; ctx.font = "46px Georgia"; ctx.fillText("Please speak softly", 512, 252);
  const texture = new THREE.CanvasTexture(canvas); texture.colorSpace = THREE.SRGBColorSpace;
  const face = new THREE.Mesh(new THREE.PlaneGeometry(4.5, 1.4), new THREE.MeshBasicMaterial({ map: texture }));
  face.position.set(x, y, z - 0.07); face.rotation.y = Math.PI; scene.add(face);   // faces the room
}

// Soft synthesized ambient music (no audio file needed). Browsers only allow sound after a click or key press.
function createQuietMusic() {
  let ctx: AudioContext | null = null;
  let bus: GainNode | null = null;
  let timer = 0;
  let nextChord = 0;
  let chordIndex = 0;
  const chords = [
    [130.81, 261.63, 329.63, 392.0, 493.88], // C major 7
    [110.0, 220.0, 261.63, 329.63, 392.0],   // A minor 7
    [87.31, 174.61, 261.63, 329.63, 440.0],  // F major 7
    [98.0, 196.0, 246.94, 293.66, 329.63],   // G 6
  ];
  const melody = [523.25, 587.33, 659.25, 783.99, 880.0];
  const tone = (freq: number, when: number, length: number, peak: number, type: OscillatorType) => {
    if (!ctx || !bus) return;
    const osc = ctx.createOscillator(); const env = ctx.createGain();
    osc.type = type; osc.frequency.value = freq;
    env.gain.setValueAtTime(0, when);
    env.gain.linearRampToValueAtTime(peak, when + length * 0.4);
    env.gain.linearRampToValueAtTime(0, when + length);
    osc.connect(env); env.connect(bus);
    osc.start(when); osc.stop(when + length + 0.05);
  };
  const schedule = () => {
    if (!ctx) return;
    while (nextChord < ctx.currentTime + 3) {
      const chord = chords[chordIndex % chords.length];
      chord.forEach((f, i) => tone(f, nextChord + i * 0.12, 9, i === 0 ? 0.05 : 0.028, "sine"));
      for (const offset of [1.5, 3.2, 5.0, 6.4]) {
        if (Math.random() < 0.7) tone(melody[Math.floor(Math.random() * melody.length)], nextChord + offset, 2.6, 0.018, "triangle");
      }
      nextChord += 8; chordIndex += 1;
    }
  };
  const build = () => {
    const AudioCtor = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    const audio = new AudioCtor();
    const master = audio.createGain(); master.gain.value = 0.55; master.connect(audio.destination);
    const soften = audio.createBiquadFilter(); soften.type = "lowpass"; soften.frequency.value = 1500;
    const input = audio.createGain(); input.connect(soften); soften.connect(master);
    const echo = audio.createDelay(1.5); echo.delayTime.value = 0.55;
    const feedback = audio.createGain(); feedback.gain.value = 0.38;
    soften.connect(echo); echo.connect(feedback); feedback.connect(echo); echo.connect(master);
    ctx = audio; bus = input;
    nextChord = audio.currentTime + 0.1; chordIndex = 0;
  };
  return {
    async start() {
      if (!ctx) build();
      const audio = ctx as AudioContext | null;
      if (!audio) return;
      if (audio.state === "suspended") await audio.resume();
      if (!timer) { schedule(); timer = window.setInterval(schedule, 1000); }
    },
    stop() { window.clearInterval(timer); timer = 0; void (ctx as AudioContext | null)?.suspend(); },
    dispose() { window.clearInterval(timer); timer = 0; void (ctx as AudioContext | null)?.close(); ctx = null; bus = null; },
  };
}
type QuietMusic = ReturnType<typeof createQuietMusic>;

export default function ThreeLibrary({ books, focusBookId, onSelect, onBrowse }: Props) {
  const hostRef = useRef<HTMLDivElement>(null);
  const sceneControl = useRef<SceneControl | null>(null);
  const onSelectRef = useRef(onSelect);
  const [sceneError, setSceneError] = useState("");
  const [locked, setLocked] = useState(false);
  const [contextHelp, setContextHelp] = useState(false);
  const [musicOn, setMusicOn] = useState(true);
  const musicOnRef = useRef(true);
  const musicRef = useRef<QuietMusic | null>(null);
  if (!musicRef.current) musicRef.current = createQuietMusic();
  onSelectRef.current = onSelect;
  const onBrowseRef = useRef(onBrowse);
  onBrowseRef.current = onBrowse;

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    let renderer: THREE.WebGLRenderer;
    try {
      renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });
    } catch {
      setSceneError("This browser could not start WebGL. The accessible book catalogue is still available from the navigation above.");
      return;
    }
    setSceneError("");
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.7));
    renderer.setSize(host.clientWidth, host.clientHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.08;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.domElement.className = "library-canvas";
    renderer.domElement.setAttribute("aria-label", "Interactive 3D university library. Use W, A, S and D to walk, mouse to look, and click a labeled book to inspect it.");
    host.prepend(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color("#d9e2e2");
    scene.fog = new THREE.Fog("#d9e2e2", 24, 62);
    const camera = new THREE.PerspectiveCamera(72, host.clientWidth / Math.max(host.clientHeight, 1), 0.1, 100);
    camera.position.set(0, 1.65, 12.5);
    let yaw = 0;
    let pitch = -0.035;
    camera.rotation.order = "YXZ";
    const hemisphere = new THREE.HemisphereLight("#fff9e9", "#747c77", 2.2);
    scene.add(hemisphere);
    const sun = new THREE.DirectionalLight("#fff2d6", 3.1);
    sun.position.set(-7, 12, 5);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -18; sun.shadow.camera.right = 18; sun.shadow.camera.top = 18; sun.shadow.camera.bottom = -18;
    sun.shadow.bias = -0.0004;
    scene.add(sun);
    const windowGlow = new THREE.PointLight("#d8ebf0", 3.2, 27, 1.8);
    windowGlow.position.set(9, 4.7, 0); scene.add(windowGlow);

    // Carpet over the whole floor.
    const floorMat = new THREE.MeshStandardMaterial({ color: "#5f6e86", roughness: 1 });
    new THREE.TextureLoader().load(CARPET_TEXTURE, (carpet) => {
      carpet.wrapS = carpet.wrapT = THREE.RepeatWrapping;
      carpet.repeat.set(8, 10);
      carpet.colorSpace = THREE.SRGBColorSpace;
      carpet.anisotropy = renderer.capabilities.getMaxAnisotropy();
      floorMat.map = carpet; floorMat.color.set("#ffffff"); floorMat.needsUpdate = true;
    });
    const floor = new THREE.Mesh(new THREE.PlaneGeometry(25, 31), floorMat);
    floor.rotation.x = -Math.PI / 2; floor.position.set(0, 0, -0.5); floor.receiveShadow = true; scene.add(floor);
    const wallMat = new THREE.MeshStandardMaterial({ color: "#e9e8df", roughness: 0.95 });
    const backWall = new THREE.Mesh(new THREE.BoxGeometry(24, 7, 0.28), wallMat);
    backWall.position.set(0, 3.5, -16.15); backWall.receiveShadow = true; scene.add(backWall);
    const frontWall = new THREE.Mesh(new THREE.BoxGeometry(24, 7, 0.28), wallMat);
    frontWall.position.set(0, 3.5, 15.15); scene.add(frontWall);
    const leftWall = new THREE.Mesh(new THREE.BoxGeometry(0.28, 7, 31.5), wallMat);
    leftWall.position.set(-12.1, 3.5, -0.5); leftWall.receiveShadow = true; scene.add(leftWall);
    // East wall with a floor-to-5.42 window opening, so the glass reaches the floor and the view is fully visible.
    const rightWallParts: Array<[number, number, number, number]> = [ // [height, length, y, z]
      [1.58, 31.5, 6.21, -0.5],
      [5.42, 0.7, 2.71, -15.9],
      [5.42, 1.4, 2.71, 14.55],
    ];
    for (const [h, len, y, z] of rightWallParts) {
      const part = new THREE.Mesh(new THREE.BoxGeometry(0.28, h, len), wallMat);
      part.position.set(12.1, y, z); part.receiveShadow = true; scene.add(part);
    }
    const ceiling = new THREE.Mesh(new THREE.PlaneGeometry(24, 31.5), new THREE.MeshStandardMaterial({ color: "#f4f1e8", roughness: 0.97 }));
    ceiling.rotation.x = Math.PI / 2; ceiling.position.set(0, 6.95, -0.5); scene.add(ceiling);
    const trimMat = new THREE.MeshStandardMaterial({ color: "#d0cfc4", roughness: 0.82 });
    for (const z of [-15.8, 14.9]) addBox(scene, new THREE.BoxGeometry(24, 0.12, 0.2), trimMat, 0, 3.05, z);
    addBox(scene, new THREE.BoxGeometry(0.2, 0.12, 31), trimMat, -11.85, 3.05, -0.5);

    // Full-height glass along the east side recreates the airy window wall in the reference photo.
    const glassMat = new THREE.MeshPhysicalMaterial({ color: "#bdd5dc", roughness: 0.13, metalness: 0.02, transparent: true, opacity: 0.14, side: THREE.DoubleSide });
    const mullionMat = new THREE.MeshStandardMaterial({ color: "#657a80", metalness: 0.38, roughness: 0.35 });
    for (let i = 0; i < 8; i++) {
      const z = -13.8 + i * 3.7;
      const pane = new THREE.Mesh(new THREE.BoxGeometry(0.055, 5.42, 3.5), glassMat);
      pane.position.set(11.93, 2.71, z); scene.add(pane);
      addBox(scene, new THREE.BoxGeometry(0.1, 5.5, 0.09), mullionMat, 11.85, 2.75, z - 1.83);
      addBox(scene, new THREE.BoxGeometry(0.1, 5.5, 0.09), mullionMat, 11.85, 2.75, z + 1.83);
    }
    addBox(scene, new THREE.BoxGeometry(0.2, 0.16, 31), mullionMat, 11.8, 5.72, -0.5);

    // Outside the glass: sky, paving and the photo as a distant backdrop (unlit, no fog, true colours).
    const unlit = (extra: THREE.MeshBasicMaterialParameters) => new THREE.MeshBasicMaterial({ fog: false, toneMapped: false, ...extra });
    const sky = new THREE.Mesh(new THREE.PlaneGeometry(130, 70), unlit({ color: "#1f84c6" }));
    sky.position.set(26.8, 28, 0); sky.rotation.y = -Math.PI / 2; scene.add(sky);
    const outsideGround = new THREE.Mesh(new THREE.PlaneGeometry(15.8, 90), unlit({ color: "#a09164" }));
    outsideGround.rotation.x = -Math.PI / 2; outsideGround.position.set(20.1, -0.03, 0); scene.add(outsideGround);
    new THREE.TextureLoader().load(WINDOW_VIEW, (view) => {
      view.colorSpace = THREE.SRGBColorSpace;
      view.anisotropy = renderer.capabilities.getMaxAnisotropy();
      // One big photo just outside the glass, covering the whole window wall.
      const viewW = 36;
      const viewH = viewW / WINDOW_VIEW_ASPECT;
      const viewBaseY = 0.0; // height of the building's base; lower shows more of the roof and pyramids
      const photo = new THREE.Mesh(new THREE.PlaneGeometry(viewW, viewH), unlit({ map: view }));
      // The building's base sits about 18% up the photo.
      photo.position.set(14, viewBaseY + viewH * (0.5 - 0.18), -0.85);
      photo.rotation.y = -Math.PI / 2;
      scene.add(photo);
    });
    // Soft daylight panels and quiet circular vents in the ceiling.
    const lampMat = new THREE.MeshStandardMaterial({ color: "#fffdf3", emissive: "#fff1c9", emissiveIntensity: 1.05, roughness: 0.3 });
    for (const x of [-8, -3, 3, 8]) for (const z of [-12, -5, 2, 9]) {
      const lamp = new THREE.Mesh(new THREE.BoxGeometry(2.15, 0.065, 1.12), lampMat);
      lamp.position.set(x, 6.83, z); scene.add(lamp);
      const light = new THREE.PointLight("#fff0d2", 0.58, 7, 1.8); light.position.set(x, 6.35, z); scene.add(light);
    }
    const ventMat = new THREE.MeshStandardMaterial({ color: "#8d9795", metalness: 0.55, roughness: 0.55 });
    for (const [vx, vz] of [[-8,-2],[2,-12],[7,6]] as const) {
      const vent = new THREE.Mesh(new THREE.CylinderGeometry(0.48, 0.48, 0.045, 32), ventMat);
      vent.position.set(vx, 6.89, vz); scene.add(vent);
      const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.13, 0.055, 16), new THREE.MeshStandardMaterial({ color: "#566766", metalness: 0.45 }));
      hub.position.set(vx, 6.89, vz); scene.add(hub);
    }

    // Door at the far left of the back wall, librarian desk on the front wall, round tables along the right wall, rectangular tables elsewhere.
    buildDoubleDoor(scene, DOOR_X, -15.96);
    for (const z of [-9, 0, 9]) buildRoundTable(scene, 8, z, "#b99468", "#57686a");
    for (const [x, z] of [[-4, -6], [1.5, -6], [-4, 5], [1.5, 5]] as const) buildStudyTable(scene, x, z, "#b99468", "#57686a");
    buildLibrarianDesk(scene, DESK_X, DESK_Z);
    buildQuietScreen(scene, 0, 4.9, 14.93);   // "Keep quiet" screen, top middle of the front wall
    buildLibrarianDesk(scene, BACK_DESK_X, BACK_DESK_Z, Math.PI);

    const wood = new THREE.MeshStandardMaterial({ color: "#b68e62", roughness: 0.8 });
    const deepWood = new THREE.MeshStandardMaterial({ color: "#70543b", roughness: 0.84 });
    const rack = new THREE.Group(); scene.add(rack);
    const sideBoard = new THREE.BoxGeometry(0.78, 0.1, BAY_LENGTH);
    const sideUpright = new THREE.BoxGeometry(0.72, 2.85, 0.12);
    const backBoard = new THREE.BoxGeometry(BACK_BAY_LENGTH, 0.1, 0.78);
    const backUpright = new THREE.BoxGeometry(0.12, 2.85, 0.72);
    for (let row = 0; row < 6; row++) {
      if (row === REMOVED_ROW) continue;
      const bay = bayOf(row);
      for (const level of [0.43, 0.98, 1.53, 2.08, 2.63]) {
        const board = new THREE.Mesh(bay.onBack ? backBoard : sideBoard, wood);
        board.position.set(bay.x, level, bay.z); board.receiveShadow = true; board.castShadow = true; rack.add(board);
      }
      for (const d of [-bay.length / 2 + 0.06, 0, bay.length / 2 - 0.06]) {
        const upright = new THREE.Mesh(bay.onBack ? backUpright : sideUpright, deepWood);
        upright.position.set(bay.onBack ? bay.x + d : bay.x, 1.48, bay.onBack ? bay.z : bay.z + d); upright.castShadow = true; rack.add(upright);
      }
      const endLabel = document.createElement("canvas"); endLabel.width = 256; endLabel.height = 128;
      const labelCtx = endLabel.getContext("2d");
      if (labelCtx) {
        labelCtx.fillStyle = "#edf0e8"; labelCtx.fillRect(0, 0, 256, 128);
        labelCtx.fillStyle = "#324f63"; labelCtx.font = "bold 54px Georgia"; labelCtx.fillText(String.fromCharCode(65 + row), 21, 70);
        labelCtx.fillStyle = "#737e78"; labelCtx.font = "20px monospace"; labelCtx.fillText("THE STACKS", 96, 70);
        const texture = new THREE.CanvasTexture(endLabel); texture.colorSpace = THREE.SRGBColorSpace;
        const sign = new THREE.Mesh(new THREE.PlaneGeometry(0.85, 0.42), new THREE.MeshBasicMaterial({ map: texture, side: THREE.DoubleSide }));
        sign.position.set(bay.onBack ? bay.x : bay.x - bay.fx * 0.35, 3.3, bay.onBack ? -15.9 : bay.z);
        sign.rotation.y = bay.onBack ? 0 : Math.PI / 2; rack.add(sign);
      }
    }

    const catalogLocations = new Map<number, THREE.Vector3>();
    const selectable: THREE.Object3D[] = [];
    const positionsTaken = new Set<string>();
    // Permanent row numbers at the left end of every shelf tier (including empty rows).
    for (let bayIndex = 0; bayIndex < 6; bayIndex++) {
      if (bayIndex === REMOVED_ROW) continue;
      const bay = bayOf(bayIndex);
      for (let level = 0; level < SHELF_LEVELS.length; level++) {
        const canvas = document.createElement("canvas"); canvas.width = 256; canvas.height = 192;
        const ctx = canvas.getContext("2d");
        if (!ctx) continue;
        ctx.fillStyle = "#efe5cf"; ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.strokeStyle = "#8b714a"; ctx.lineWidth = 10; ctx.strokeRect(5, 5, 246, 182);
        ctx.fillStyle = "#263b3d"; ctx.font = "bold 118px Georgia"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillText(String(level + 1), 128, 100);
        ctx.fillStyle = "#65736e"; ctx.font = "bold 26px sans-serif"; ctx.fillText("ROW", 128, 165);
        const texture = new THREE.CanvasTexture(canvas); texture.colorSpace = THREE.SRGBColorSpace;
        const tag = new THREE.Mesh(new THREE.PlaneGeometry(0.34, 0.26), new THREE.MeshBasicMaterial({ map: texture, side: THREE.DoubleSide }));
        const y = SHELF_LEVELS[level] + 0.2;
        if (bay.onBack) {
          tag.position.set(bay.x - bay.length / 2 - 0.2, y, bay.z + 0.48);
          tag.lookAt(tag.position.x, y, bay.z + 2);
        } else {
          tag.position.set(bay.x + 0.48, y, bay.z + bay.length / 2 + 0.2);
          tag.lookAt(bay.x + 2, y, tag.position.z);
        }
        rack.add(tag);
      }
    }

    const spineBase = new THREE.BoxGeometry(0.21, 0.39, 0.52);
    const backBookGeometry = new RoundedBoxGeometry(0.14, 0.33, 0.14, 2, 0.015);
    const sharedBackMaterials = BOOK_COLORS.map((color) => new THREE.MeshStandardMaterial({ color, roughness: 0.8 }));
    const backMeshes: THREE.InstancedMesh[] = [];
    // Where each catalogue book stands. Books keep their shelfRow/shelfSlot, except those from the
    // removed shelf D, which move to the nearest free slot on E, F, C, B or A.
    const clampBay = (r: number) => Math.max(0, Math.min(5, r));
    const clampSlot = (n: number) => Math.max(0, Math.min(SHELF_COPY_SLOTS - 1, n));
    const shelfIndex = (book: LibraryBook) => ({ A: 0, B: 1, C: 2, D: 3, E: 4, F: 5 }[book.shelf.trim().toUpperCase()] ?? clampBay(book.shelfRow));
    const placements = (() => {
      const taken = new Set<string>();
      const result = new Map<number, { row: number; slot: number; level: number }>();
      const ordered = books.map((book, index) => ({ book, index })).sort((a, b) => {
        const ka = `${a.book.shelf.toUpperCase()}-${a.book.shelfRow}-${a.book.title.toLocaleLowerCase()}-${a.book.author.toLocaleLowerCase()}`;
        const kb = `${b.book.shelf.toUpperCase()}-${b.book.shelfRow}-${b.book.title.toLocaleLowerCase()}-${b.book.author.toLocaleLowerCase()}`;
        return ka.localeCompare(kb) || a.book.shelfSlot - b.book.shelfSlot || a.index - b.index;
      });
      for (const { book, index } of ordered) {
        let row = shelfIndex(book);
        if (row === REMOVED_ROW) row = 4;
        const level = Math.max(0, Math.min(SHELF_LEVELS.length - 1, book.shelfRow));
        let slot = clampSlot(book.shelfSlot);
        const copies = Math.max(1, Math.min(SHELF_COPY_SLOTS, book.totalCopies ?? 1));
        const isFree = (at: number) => at + copies <= SHELF_COPY_SLOTS && Array.from({ length: copies }, (_, n) => `${row}-${level}-${at + n}`).every(key => !taken.has(key));
        while (slot < SHELF_COPY_SLOTS && !isFree(slot)) slot++;
        if (slot >= SHELF_COPY_SLOTS) {
          const alternative = [0, 1, 2, 4, 5].find(candidate => candidate !== row && Array.from({ length: SHELF_COPY_SLOTS - copies + 1 }, (_, n) => n).some(at => Array.from({ length: copies }, (_, c) => `${candidate}-${level}-${at + c}`).every(key => !taken.has(key))));
          if (alternative !== undefined) {
            row = alternative;
            slot = Array.from({ length: SHELF_COPY_SLOTS - copies + 1 }, (_, n) => n).find(at => Array.from({ length: copies }, (_, c) => !taken.has(`${row}-${level}-${at + c}`))) ?? 0;
          } else slot = SHELF_COPY_SLOTS - copies;
        }
        for (let n = 0; n < copies; n++) taken.add(`${row}-${level}-${slot + n}`);
        result.set(index, { row, slot, level });
      }
      return result;
    })();
    for (let row = 0; row < 6; row++) for (let level = 0; level < SHELF_LEVELS.length; level++) {
      if (row === REMOVED_ROW) continue;
      const bay = bayOf(row);
      const lenScale = bay.step / SLOT_STEP;
      const freePositions: Array<{ x: number; z: number; y: number; color: number; rotation: number }> = [];
      for (let slot = 0; slot < SHELF_COPY_SLOTS; slot++) {
        const { x, z } = slotPos(row, slot);
        const occupiedByCatalogueBook = books.some((_, bookIndex) => {
          const spot = placements.get(bookIndex);
          return !!spot && spot.row === row && spot.level === level && slot >= spot.slot && slot < spot.slot + Math.max(1, books[bookIndex]?.totalCopies ?? 1);
        });
        if (occupiedByCatalogueBook) continue;
        freePositions.push({ x, z, y: SHELF_LEVELS[level] + 0.2, color: (slot * 7 + row * 3 + level * 2) % BOOK_COLORS.length, rotation: ((slot % 3) - 1) * 0.055 });
      }
      const perColor = sharedBackMaterials.map(() => [] as Array<{ x: number; z: number; y: number; rotation: number }>);
      freePositions.forEach((point) => perColor[point.color].push(point));
      perColor.forEach((points, colorIndex) => {
        if (points.length === 0) return;
        const instanced = new THREE.InstancedMesh(backBookGeometry, sharedBackMaterials[colorIndex], points.length);
        const dummy = new THREE.Object3D();
        points.forEach((point, index) => {
          dummy.position.set(point.x + bay.fx * 0.03, point.y, point.z + bay.fz * 0.03);
          dummy.rotation.y = (bay.onBack ? Math.PI / 2 : 0) + Math.PI / 2 + point.rotation;
          dummy.scale.set(1, 1, 1);
          dummy.updateMatrix(); instanced.setMatrixAt(index, dummy.matrix);
        });
        instanced.instanceMatrix.needsUpdate = true; instanced.castShadow = false; instanced.receiveShadow = false; rack.add(instanced); backMeshes.push(instanced);
      });
    }

    books.forEach((book, index) => {
      const spot = placements.get(index) ?? { row: shelfIndex(book), slot: clampSlot(book.shelfSlot), level: Math.max(0, Math.min(SHELF_LEVELS.length - 1, book.shelfRow)) };
      const row = spot.row;
      const bay = bayOf(row);
      const levelIndex = spot.level;
      const y = SHELF_LEVELS[levelIndex] + 0.2;
      const bookColor = new THREE.MeshStandardMaterial({ color: book.coverColor, roughness: 0.76 });
      const pagesMat = new THREE.MeshStandardMaterial({ color: "#e8dfc8", roughness: 0.92 });
      const copies = Math.max(1, Math.min(SHELF_COPY_SLOTS, book.totalCopies ?? 1));
      let firstPosition = new THREE.Vector3();
      for (let copy = 0; copy < copies; copy++) {
        const { x: bx, z } = slotPos(row, spot.slot + copy);
        const bookMesh = new THREE.Group();
        // Rounded page block, front/back boards, and a raised spine make each copy read as a bound book.
        const pages = new THREE.Mesh(new RoundedBoxGeometry(0.12, 0.34, 0.14, 3, 0.015), pagesMat);
        bookMesh.add(pages);
        const frontBoard = new THREE.Mesh(new RoundedBoxGeometry(0.022, 0.39, 0.17, 2, 0.008), bookColor);
        frontBoard.position.x = 0.063; bookMesh.add(frontBoard);
        const rearBoard = new THREE.Mesh(new RoundedBoxGeometry(0.022, 0.39, 0.17, 2, 0.008), bookColor);
        rearBoard.position.x = -0.063; bookMesh.add(rearBoard);
        const spine = new THREE.Mesh(new RoundedBoxGeometry(0.15, 0.39, 0.022, 2, 0.008), bookColor);
        spine.position.z = -0.063; bookMesh.add(spine);
        // Turn each volume 90° so the narrow book thickness runs along the shelf and more fit in a bay.
        bookMesh.position.set(bx + bay.fx * 0.06, y, z + bay.fz * 0.06);
        // Face the narrow spine into the room after rotating the book along the shelf.
        bookMesh.rotation.y = (bay.onBack ? Math.PI : -Math.PI / 2) + ((index % 3) - 1) * 0.015;
        bookMesh.scale.y = 0.9 + ((index * 7) % 5) * 0.045;
        bookMesh.traverse(child => { if (child instanceof THREE.Mesh) { child.castShadow = true; } });
        // Independent, invisible pick target centered on each copy. Visible geometry can be
        // rotated without making clicks land beside the volume or miss the group entirely.
        const hitbox = new THREE.Mesh(
          new THREE.BoxGeometry(0.22, 0.44, 0.22),
          new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, colorWrite: false, side: THREE.DoubleSide, depthWrite: false }),
        );
        hitbox.userData.bookId = book.id;
        bookMesh.add(hitbox);
        selectable.push(hitbox);
        if (copy === 0) {
          firstPosition.set(bx, y, z);
          const texture = makeSpineTexture(book.title, book.accentColor);
          if (texture) {
            const label = new THREE.Mesh(new THREE.PlaneGeometry(0.15, 0.31), new THREE.MeshBasicMaterial({ map: texture, side: THREE.DoubleSide }));
            // Keep the title on the front face toward the room, not on the rotated side.
            label.position.set(bx + bay.fx * 0.13, y, z + bay.fz * 0.13);
            label.lookAt(bx + bay.fx, y, z + bay.fz);
            label.userData.bookId = book.id;
            rack.add(label); selectable.push(label);
          }
        }
        rack.add(bookMesh);
      }
      catalogLocations.set(book.id, firstPosition);
      positionsTaken.add(`${row}-${levelIndex}-${spot.slot}`);
    });

    const beacon = new THREE.Mesh(new THREE.RingGeometry(0.3, 0.38, 40), new THREE.MeshBasicMaterial({ color: "#d1ad67", transparent: true, opacity: 0.96, side: THREE.DoubleSide }));
    beacon.visible = false; scene.add(beacon);
    const beaconLight = new THREE.PointLight("#f3d590", 2.4, 5, 2); beaconLight.visible = false; scene.add(beaconLight);

    // Solid tables (centre x/z and half-size) so the visitor walks around them.
    const obstacles = [
      { x: BACK_DESK_X, z: BACK_DESK_Z - 0.6, hx: 1.8, hz: 1.3 },                                    // back-wall librarian desk
      { x: DESK_X, z: DESK_Z + 0.6, hx: 1.8, hz: 1.3 },                                              // librarian desk
      ...[-9, 0, 9].map((z) => ({ x: 8, z, hx: 2.1, hz: 2.1 })),                                   // round tables
      ...([[-4, -6], [1.5, -6], [-4, 5], [1.5, 5]] as const).map(([x, z]) => ({ x, z, hx: 2.4, hz: 1.6 })), // rectangular tables
    ];
    const blocked = (x: number, z: number) => obstacles.some((o) => Math.abs(x - o.x) < o.hx && Math.abs(z - o.z) < o.hz);

    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();
    const keyState = { forward: false, backward: false, left: false, right: false };
    const rendererCanvas = renderer.domElement;
    let priorTime = performance.now();
    let frameId = 0;
    let focusPosition: THREE.Vector3 | null = null;
    const setFocus = (id: number) => {
      const position = catalogLocations.get(id);
      if (!position) return;
      focusPosition = position.clone();
      const onBack = position.z < -15;
      const side = position.x < 0 ? 1 : -1;
      if (onBack) camera.position.set(position.x + 1.2, 1.58, position.z + 2.4);
      else camera.position.set(position.x + side * 2.4, 1.58, position.z + 1.6);
      const dx = position.x - camera.position.x;
      const dz = position.z - camera.position.z;
      yaw = Math.atan2(-dx, -dz);
      pitch = THREE.MathUtils.clamp(Math.atan2(position.y - camera.position.y, Math.hypot(dx, dz)), -0.62, 0.55);
      camera.rotation.set(pitch, yaw, 0, "YXZ");
      beacon.position.set(onBack ? position.x : position.x + side * 0.23, position.y, onBack ? position.z + 0.23 : position.z);
      beacon.lookAt(camera.position.x, position.y, camera.position.z);
      beacon.visible = true; beaconLight.position.copy(position).setY(position.y + 0.35); beaconLight.visible = true;
      setContextHelp(true);
      window.setTimeout(() => setContextHelp(false), 4200);
    };
    const selectAt = (nx: number, ny: number) => {
      mouse.set(nx, ny); raycaster.setFromCamera(mouse, camera);
      const intersections = raycaster.intersectObjects(selectable, false);
      const id = intersections[0]?.object.userData.bookId as number | undefined;
      if (id) {
        const book = books.find((item) => item.id === id);
        if (book) {
          // Release the mouse so the cursor reappears and the details panel can be clicked.
          if (document.pointerLockElement === rendererCanvas) document.exitPointerLock();
          onSelectRef.current(book);
        }
        return true;
      }
      return false;
    };
    sceneControl.current = { focus: setFocus, selectCenter: () => selectAt(0, 0) };

    const kickMusic = () => { if (musicOnRef.current) musicRef.current?.start().catch(() => {}); };
    const onPointerDown = (event: PointerEvent) => {
      if (event.button !== 0) return;
      kickMusic();
      if (document.pointerLockElement === rendererCanvas) {
        if (!selectAt(0, 0)) setContextHelp((v) => !v);
        return;
      }
      const rect = rendererCanvas.getBoundingClientRect();
      const nx = ((event.clientX - rect.left) / rect.width) * 2 - 1;
      const ny = -((event.clientY - rect.top) / rect.height) * 2 + 1;
      if (selectAt(nx, ny)) return;
      setContextHelp(true);
      if (rendererCanvas.requestPointerLock) rendererCanvas.requestPointerLock();
    };
    const onPointerLockChange = () => setLocked(document.pointerLockElement === rendererCanvas);
    const onMouseMove = (event: MouseEvent) => {
      if (document.pointerLockElement !== rendererCanvas) return;
      yaw -= event.movementX * 0.0023;
      pitch -= event.movementY * 0.0019;
      pitch = Math.max(-0.78, Math.min(0.66, pitch));
    };
    const onKeyDown = (event: KeyboardEvent) => {
      const key = event.key.toLowerCase();
      if (["w", "a", "s", "d", "arrowup", "arrowdown", "arrowleft", "arrowright"].includes(key)) { event.preventDefault(); kickMusic(); }
      if (key === "w" || key === "arrowup") keyState.forward = true;
      if (key === "s" || key === "arrowdown") keyState.backward = true;
      if (key === "a" || key === "arrowleft") keyState.left = true;
      if (key === "d" || key === "arrowright") keyState.right = true;
    };
    const onKeyUp = (event: KeyboardEvent) => {
      const key = event.key.toLowerCase();
      if (key === "w" || key === "arrowup") keyState.forward = false;
      if (key === "s" || key === "arrowdown") keyState.backward = false;
      if (key === "a" || key === "arrowleft") keyState.left = false;
      if (key === "d" || key === "arrowright") keyState.right = false;
    };
    const onBlur = () => { keyState.forward = keyState.backward = keyState.left = keyState.right = false; };
    rendererCanvas.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("pointerlockchange", onPointerLockChange);
    document.addEventListener("mousemove", onMouseMove);
    window.addEventListener("keydown", onKeyDown);
    window.addEventListener("keyup", onKeyUp);
    window.addEventListener("blur", onBlur);

    const resize = () => {
      if (!host || host.clientWidth === 0) return;
      camera.aspect = host.clientWidth / host.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(host.clientWidth, host.clientHeight);
    };
    const observer = new ResizeObserver(resize);
    observer.observe(host);
    const moveMobile = (direction: keyof typeof keyState, pressed: boolean) => { keyState[direction] = pressed; };
    host.dataset.mobileControl = "ready";

    const animate = (time: number) => {
  frameId = requestAnimationFrame(animate);
  const delta = Math.min((time - priorTime) / 1000, 0.045);
  priorTime = time;

  camera.rotation.set(pitch, yaw, 0, "YXZ");

  const forward = Number(keyState.forward) - Number(keyState.backward);
  const strafe = Number(keyState.right) - Number(keyState.left);

  if (forward || strafe) {
    // Clear item focus when moving so controls respond freely
    if (focusPosition) {
      focusPosition = null;
      beacon.visible = false;
      beaconLight.visible = false;
    }

    const speed = 3.4 * delta;
    const sideSpeed = 3.2 * delta;

    // Corrected sign directions for Three.js YXZ coordinates
    const dx = -Math.sin(yaw) * forward * speed + Math.cos(yaw) * strafe * sideSpeed;
    const dz = -Math.cos(yaw) * forward * speed - Math.sin(yaw) * strafe * sideSpeed;

    const nextX = THREE.MathUtils.clamp(camera.position.x + dx, -10.4, 10.4);
    const nextZ = THREE.MathUtils.clamp(camera.position.z + dz, -14.6, 14.2);

    if (!blocked(nextX, camera.position.z)) camera.position.x = nextX;
    if (!blocked(camera.position.x, nextZ)) camera.position.z = nextZ;
  }

    if (focusPosition && beacon.visible) {
      const pulse = 1 + Math.sin(time * 0.0032) * 0.08;
      beacon.scale.setScalar(pulse);
      beaconLight.intensity = 1.9 + (Math.sin(time * 0.0032) + 1) * 0.45;
    }

    renderer.render(scene, camera);
  };
    frameId = requestAnimationFrame(animate);

    // Expose simple tap-and-hold directions to the overlaid controls.
    (host as HTMLDivElement & { setMobileMove?: (direction: keyof typeof keyState, pressed: boolean) => void }).setMobileMove = moveMobile;
    return () => {
      cancelAnimationFrame(frameId);
      observer.disconnect();
      rendererCanvas.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("pointerlockchange", onPointerLockChange);
      document.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("keydown", onKeyDown);
      window.removeEventListener("keyup", onKeyUp);
      window.removeEventListener("blur", onBlur);
      if (document.pointerLockElement === rendererCanvas) document.exitPointerLock();
      sceneControl.current = null;
      while (scene.children.length) {
        const child = scene.children[0]; scene.remove(child);
      }
      scene.traverse((object) => {
        if (object instanceof THREE.Mesh) {
          object.geometry.dispose();
          const materials = Array.isArray(object.material) ? object.material : [object.material];
          materials.forEach((material) => {
            const map = (material as THREE.MeshStandardMaterial).map;
            map?.dispose(); material.dispose();
          });
        }
      });
      sharedBackMaterials.forEach((material) => material.dispose());
      renderer.dispose(); rendererCanvas.remove();
    };
  }, [books]);

  useEffect(() => () => { musicRef.current?.dispose(); }, []);

  // Jump to the Browse books tab (button click or the B key).
  const goBrowse = () => {
    if (document.pointerLockElement) document.exitPointerLock();
    if (onBrowseRef.current) onBrowseRef.current();
    else window.location.assign("/browse-books"); // fallback if the parent doesn't pass onBrowse
  };
  const goBrowseRef = useRef(goBrowse);
  goBrowseRef.current = goBrowse;

  useEffect(() => {
    const onBrowseKey = (event: KeyboardEvent) => {
      if (event.key.toLowerCase() !== "b" || event.ctrlKey || event.metaKey || event.altKey || event.repeat) return;
      const t = event.target as HTMLElement | null;
      if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.tagName === "SELECT" || t.isContentEditable)) return;
      event.preventDefault();
      goBrowseRef.current();
    };
    window.addEventListener("keydown", onBrowseKey);
    return () => window.removeEventListener("keydown", onBrowseKey);
  }, []);

  useEffect(() => {
    if (focusBookId) sceneControl.current?.focus(focusBookId);
  }, [focusBookId, books]);

  const toggleMusic = () => {
    const next = !musicOn;
    setMusicOn(next); musicOnRef.current = next;
    if (next) musicRef.current?.start().catch(() => {});
    else musicRef.current?.stop();
  };

  const moveBy = (direction: string, pressed: boolean) => {
    const host = hostRef.current as (HTMLDivElement & { setMobileMove?: (direction: "forward" | "backward" | "left" | "right", pressed: boolean) => void }) | null;
    const map: Record<string, "forward" | "backward" | "left" | "right"> = { forward: "forward", backward: "backward", left: "left", right: "right" };
    if (map[direction]) host?.setMobileMove?.(map[direction], pressed);
  };

  return <div className="three-library-host" ref={hostRef}>
    {sceneError && <div className="scene-fallback"><div className="fallback-card"><span className="eyebrow">ACCESSIBLE BROWSING</span><h2>Browse without the 3D view</h2><p>{sceneError}</p><p>Search, inspect, borrow, or locate any title from Browse books.</p><a className="button button-primary" href="/browse-books">Browse books</a></div></div>}
    <div className="scene-crosshair" aria-hidden="true" />
    <button type="button" aria-label={musicOn ? "Mute library music" : "Play quiet library music"} aria-pressed={musicOn} onClick={toggleMusic}
      style={{ position: "absolute", top: 14, right: 14, zIndex: 6, width: 38, height: 38, borderRadius: 999, border: "1px solid rgba(255,255,255,0.5)", background: "rgba(36,52,56,0.72)", color: "#f3efe3", display: "grid", placeItems: "center", cursor: "pointer" }}>
      {musicOn ? <Volume2 size={16} /> : <VolumeX size={16} />}
    </button>
    {contextHelp && <div className="scene-pointer-help"><MousePointer2 size={13} /> Look around · center a title and click to inspect</div>}
    <div className="mobile-pad" aria-label="Touch navigation controls">
      <button type="button" aria-label="Walk forward" onPointerDown={(e) => { e.preventDefault(); moveBy("forward", true); }} onPointerUp={() => moveBy("forward", false)} onPointerLeave={() => moveBy("forward", false)} onPointerCancel={() => moveBy("forward", false)}><ArrowUp size={17} /></button>
      <button type="button" aria-label="Walk left" onPointerDown={(e) => { e.preventDefault(); moveBy("left", true); }} onPointerUp={() => moveBy("left", false)} onPointerLeave={() => moveBy("left", false)} onPointerCancel={() => moveBy("left", false)}><ArrowLeft size={17} /></button>
      <button type="button" aria-label="Walk backward" onPointerDown={(e) => { e.preventDefault(); moveBy("backward", true); }} onPointerUp={() => moveBy("backward", false)} onPointerLeave={() => moveBy("backward", false)} onPointerCancel={() => moveBy("backward", false)}><ArrowDown size={17} /></button>
      <button type="button" aria-label="Walk right" onPointerDown={(e) => { e.preventDefault(); moveBy("right", true); }} onPointerUp={() => moveBy("right", false)} onPointerLeave={() => moveBy("right", false)} onPointerCancel={() => moveBy("right", false)}><ArrowRight size={17} /></button>
    </div>
    {locked && <div className="scene-pointer-help"><MousePointer2 size={13} /> Mouse look on · Esc to release · click a book to select</div>}
  </div>;
}
